import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type AchievementButtonProps = Record<string, any>;

const AchievementButton: React.FC<AchievementButtonProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  buttonOneText = "M1 Abrams Test",
  buttonTwoText = "System Diagnostics",
  achievementColor = "#f59e0b",
  buttonBaseColor = "#121212",
  textColor = "#a3a3a3",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Safety for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Logic ---

  // Combined Panel Entrance
  const panelEntrance = spring({
    fps,
    frame: frame - 10,
    config: { damping: 14, mass: 0.8 },
  });
  const panelY = interpolate(panelEntrance, [0, 1], [60, 0]);

  // Illumination Effect on Bottom Row (Starts at 1.5 seconds)
  const illuminationStartFrame = Math.max(30, fps * 1.5);
  const illuminationBump = spring({
    fps,
    frame: frame - illuminationStartFrame,
    config: { damping: 12, mass: 0.8 },
  });

  // Clamp the progress strictly between 0 and 1 for color interpolation safety
  const illuminationProgress = interpolate(illuminationBump, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dynamic values derived from illumination progress
  const scaleModifier = illuminationBump * 0.05; 
  const totalScale = Math.max(0, panelEntrance + scaleModifier);

  // Bottom row transitions from transparent (showing buttonBaseColor) to achievementColor
  const bottomBgColor = interpolateColors(
    illuminationProgress,
    [0, 1],
    ["rgba(0,0,0,0)", achievementColor]
  );
  
  const bottomTextColor = interpolateColors(
    illuminationProgress,
    [0, 1],
    [textColor, "#050505"]
  );

  const glowSpread = interpolate(illuminationProgress, [0, 1], [0, 24]);
  
  const transparentGlow = `${achievementColor}00`;
  const bottomGlowColor = interpolateColors(
    illuminationProgress,
    [0, 1],
    [transparentGlow, achievementColor]
  );

  // --- Styles ---

  const baseRowStyle: React.CSSProperties = {
    padding: "40px 80px",
    fontFamily: robotoMonoFamily,
    textTransform: "uppercase",
    letterSpacing: "0.15em",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transition: "none",
    boxSizing: "border-box",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* HUD Decorative Background Elements */}
      {!transparentBackground && (
        <>
          <div style={{ position: "absolute", top: 32, left: 40, fontFamily: robotoMonoFamily, fontSize: 12, color: "rgba(255,255,255,0.2)", letterSpacing: "0.2em", zIndex: 1 }}>
            SYS.OP.492 // TACTICAL
          </div>
          <div style={{ position: "absolute", bottom: 32, right: 40, fontFamily: robotoMonoFamily, fontSize: 12, color: "rgba(255,255,255,0.2)", letterSpacing: "0.2em", zIndex: 1 }}>
            MALLOY STUDIO
          </div>
        </>
      )}

      {/* Combined Body Panel */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          backgroundColor: buttonBaseColor,
          border: `1px solid rgba(255, 255, 255, 0.15)`,
          borderLeft: `6px solid rgba(255, 255, 255, 0.3)`,
          transform: `translateY(${panelY}px) scale(${totalScale})`,
          opacity: interpolate(panelEntrance, [0, 0.5], [0, 1]),
          boxShadow: "inset 0px 0px 30px rgba(0,0,0,0.8)",
          zIndex: 5,
        }}
      >
        {/* Top Row (Standard) */}
        <div
          style={{
            ...baseRowStyle,
            fontSize: "84px",
            fontWeight: 900,
            color: textColor,
            borderBottom: `2px solid rgba(255, 255, 255, 0.15)`,
          }}
        >
          <span>{buttonOneText}</span>
        </div>

        {/* Bottom Row (Illuminating) */}
        <div
          style={{
            ...baseRowStyle,
            fontSize: "56px",
            fontWeight: 500,
            backgroundColor: bottomBgColor,
            color: bottomTextColor,
            boxShadow: `inset 0px 0px 30px rgba(0,0,0,0.8), 0px 0px ${glowSpread}px ${bottomGlowColor}`,
            position: "relative",
          }}
        >
          {/* Animated Checkmark Icon */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "flex-start",
              width: interpolate(illuminationProgress, [0, 1], [0, 80]),
              opacity: illuminationProgress,
              overflow: "hidden",
              transition: "none",
            }}
          >
            <svg
              width="56"
              height="56"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="square"
              strokeLinejoin="miter"
              style={{
                transform: `scale(${illuminationBump})`,
                transition: "none",
              }}
            >
              <polyline points="20 6 9 17 4 12" />
            </svg>
          </div>
          
          <span>{buttonTwoText}</span>
        </div>
      </div>

      {/* Overlay Scanlines for HUD Effect */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: `repeating-linear-gradient(
              0deg,
              transparent,
              transparent 2px,
              rgba(0, 0, 0, 0.2) 2px,
              rgba(0, 0, 0, 0.2) 4px
            )`,
            pointerEvents: "none",
            zIndex: 10,
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default AchievementButton;